// EC field KATs. Expected values generated by sw/golden.py arithmetic
// (Python, independent of the RTL): see docs/COMPLIANCE.md.
`timescale 1ns/1ps
module tb_ec_field;
    reg clk=0, rst_n=0, start=0;
    reg [1:0] op;
    reg [255:0] a,b,mod;
    wire [255:0] result;
    wire busy, done;
    integer errors=0;
    localparam [255:0] SECP = 256'hfffffffffffffffffffffffffffffffffffffffffffffffffffffffefffffc2f;
    localparam [255:0] C255 = 256'h7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffed;
    ec_field dut(.clk(clk),.rst_n(rst_n),.start(start),.op(op),
        .a(a),.b(b),.mod(mod),.result(result),.busy(busy),.done(done));
    always #5 clk = ~clk;

    task run_op(input [1:0] o, input [255:0] x, input [255:0] y,
                input [255:0] m, input [255:0] exp, input [255:0] nm);
        begin
            @(negedge clk); op=o; a=x; b=y; mod=m; start=1;
            @(negedge clk); start=0;
            wait(done); @(negedge clk);
            if (result !== exp) begin
                errors=errors+1;
                $display("FAIL %0s got=%h exp=%h", nm, result, exp);
            end else $display("PASS %0s", nm);
        end
    endtask

    initial begin
        repeat(2) @(negedge clk); rst_n=1;
        run_op(2'd2, 256'd2, 256'd3, SECP, 256'd6, "mul 2*3 secp");
        run_op(2'd2, SECP-1, SECP-1, SECP, 256'd1, "mul (p-1)^2 secp");
        run_op(2'd2, C255-2, C255-2, C255, 256'd4, "mul (p-2)^2 c25519");
        run_op(2'd2,
          256'h1234567890abcdef1234567890abcdef1234567890abcdef1234567890abcdef,
          256'hfedcba0987654321fedcba0987654321fedcba0987654321fedcba0987654321,
          SECP,
          256'h0dabcd892d293feb6a2a19b97d502825c6a865e9cd771060354652a4e4897181,
          "mul mixed secp");
        run_op(2'd0, SECP-1, SECP-1, SECP, SECP-2, "add (p-1)+(p-1)");
        run_op(2'd1, 256'd2, 256'd3, SECP, SECP-1, "sub 2-3 secp");
        if (errors==0) $display("TB_EC_FIELD PASS"); else $display("TB_EC_FIELD FAIL %0d", errors);
        $finish;
    end
endmodule
